(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[119],{1458:function(t,e,n){"use strict";n.r(e),e.default={code:"114JTaitung",title:"114-臺東縣國中",unlockCode:"114JTaitung",tasks:[{id:"Taitung-J-1",code:"114JTaitung-Taitung-J-1",title:"魔法公車車票計算",description:"歡迎來到「777魔法公車」！這條公車線路共有1號到15號共15個站點。\n在所有站點中，10號站是一個非常特別的站，我們叫它「魔法分隔站」。\n【票價規則】\n公車票價的計算分兩大步驟：先決定票種，再決定折扣。\n第一步：決定票種(一段票 vs. 兩段票)\n1. 一段票(單程票)：基本票價是10元。\n• 適用情況：你的旅程沒有跨越「魔法分隔站(10號站)」。(起訖站皆在10號站(含)之前，或皆在10號站(含)之後)。\n• 例如：從3號站到8號站。\n2. 兩段票(跨區票)：票價變成基本票價的兩倍，是20元。\n• 適用情況：你的旅程跨越了「魔法分隔站(10號站)」。\n• 例如：從7號站到12號站，或從14號站到5號站。\n第二步：幸運折扣(半票優惠)\n如果你的年齡是12歲以下(例如11歲、10歲...)，那麼恭喜你！你可以享有「幸運半票」優惠！\n• 幸運半票優惠：你計算出來的票價(無論是10元還是20元)，都只需要支付一半。",examples:[{input:"5\n8\n18",output:"10",explanation:"第5站搭到第8站，1段全票10元"},{input:"7\n12\n20",output:"20",explanation:"第7站搭到第12站，2段全票20元"},{input:"13\n10\n8",output:"5",explanation:"第13站搭到第10站，1段半票5元"}],testCases:[{input:"1\n9\n30",expectedOutput:"10",score:10},{input:"2\n11\n15",expectedOutput:"20",score:10},{input:"10\n15\n40",expectedOutput:"10",score:10},{input:"15\n1\n7",expectedOutput:"10",score:10},{input:"9\n10\n5",expectedOutput:"5",score:10},{input:"1\n15\n10",expectedOutput:"10",score:10},{input:"1\n10\n20",expectedOutput:"10",score:10},{input:"10\n1\n12",expectedOutput:"5",score:10},{input:"11\n15\n11",expectedOutput:"5",score:10},{input:"12\n8\n35",expectedOutput:"20",score:10}],difficulty:"L2",sb3Path:"m0/114JTaitung/Taitung-J-1.sb3"},{id:"Taitung-J-2",code:"114JTaitung-Taitung-J-2",title:"幸運數字彩虹樂透",description:"為了舉辦校園慈善抽獎活動，我們設計了一個簡單的「幸運數字彩虹樂透」。\n每張樂透彩券必須選出6個數字(範圍從1到49)。\n現在，我們需要設計一個抽獎系統來計算彩券是否中獎，以及獎金是多少。\n【開獎號碼】\n• 本次固定開獎號碼為：10, 18, 29, 31, 35, 36\n【中獎規則與獎金】\n• 6個：頭獎，100,000元\n• 5個：貳獎，10,000元\n• 4個：參獎，1,000元\n• 3個：肆獎，100元\n• 2個或更少：銘謝惠顧，0元",examples:[{input:"10\n18\n29\n31\n35\n36",output:"猜中6個號碼,獎金100000元",explanation:"6個號碼完全相同，獎金100000元。"},{input:"1\n2\n3\n4\n5\n6",output:"猜中0個號碼,獎金0元",explanation:"0個號碼相同，獎金0元。"}],testCases:[{input:"10 18 29 31 35 36",expectedOutput:"猜中6個號碼,獎金100000元",score:10},{input:"1 2 3 4 5 6",expectedOutput:"猜中0個號碼,獎金0元",score:10},{input:"10 18 29 31 35 45",expectedOutput:"猜中5個號碼,獎金10000元",score:10},{input:"10 18 29 40 41 42",expectedOutput:"猜中3個號碼,獎金100元",score:10},{input:"10 18 29 31 38 49",expectedOutput:"猜中4個號碼,獎金1000元",score:10},{input:"10 18 40 41 42 43",expectedOutput:"猜中2個號碼,獎金0元",score:10},{input:"10 40 41 42 43 44",expectedOutput:"猜中1個號碼,獎金0元",score:10},{input:"18 29 31 35 36 40",expectedOutput:"猜中5個號碼,獎金10000元",score:10},{input:"29 31 35 36 40 41",expectedOutput:"猜中4個號碼,獎金1000元",score:10},{input:"31 35 36 40 41 42",expectedOutput:"猜中3個號碼,獎金100元",score:10}],difficulty:"L1",sb3Path:"m0/114JTaitung/Taitung-J-2.sb3"},{id:"Taitung-J-3",code:"114JTaitung-Taitung-J-3",title:"我的健康小管家",description:"基礎代謝率(BMR)是指您的身體在完全休息狀態下，為了維持基本生命功能所需，它是您每日總能量消耗中最大的一個組成部分，通常佔您每天燃燒總卡路里的60%至70%，例如：呼吸、器官運作、體溫維持等，即使整天躺著不動也會消耗的最低熱量。BMR會隨著年紀增加或體重減輕而降低，會隨著肌肉量增加而上升。BMR就像是我們身體的「待機電力」。\n【BMR 簡易計算】\n為了簡化，我們使用一個簡化的BMR公式(參考女性BMR公式)，並將年齡固定為一個數字，只讓程式根據體重和身高來計算。我們固定年齡為14歲，簡化後BMR估算公式如下：\nBMR = 655 + (9.6*體重(kg)) + (1.8*身高(cm)) - (4.7 *14)\n程式計算出 BMR數值(取整數)後，會用這個標準來分類：\n• 小於1200：極低能量\n• 1200到1499：較低能量\n• 1500到1799：標準能量\n• 1800到2099：較高能量\n• 2100以上：極高能量",examples:[{input:"170\n55",output:"1423 較低能量",explanation:"655 + (9.6 * 55) + (1.8 * 170) - (4.7 * 14) = 1423.2 取整數 1423 1423介於1200到1499 輸出較低能量"},{input:"175\n70",output:"1576 標準能量",explanation:"655 + (9.6 * 70) + (1.8 * 175) - (4.7 * 14) = 1576.2 取整數 1576 1576介於1500到1799 輸出標準能量"}],testCases:[{input:"150\n35",expectedOutput:"1195 極低能量",score:10},{input:"160\n45",expectedOutput:"1309 較低能量",score:10},{input:"165\n50",expectedOutput:"1366 較低能量",score:10},{input:"170\n55",expectedOutput:"1423 較低能量",score:10},{input:"168\n68",expectedOutput:"1544 標準能量",score:10},{input:"180\n85",expectedOutput:"1729 標準能量",score:10},{input:"180\n95",expectedOutput:"1825 較高能量",score:10},{input:"190\n100",expectedOutput:"1891 較高能量",score:10},{input:"200\n120",expectedOutput:"2101 極高能量",score:10},{input:"175\n70",expectedOutput:"1576 標準能量",score:10}],difficulty:"L2",sb3Path:"m0/114JTaitung/Taitung-J-3.sb3"},{id:"Taitung-J-4",code:"114JTaitung-Taitung-J-4",title:"東台線上3C購物平台",description:"東台3C賣場推出線上購物大拍賣平台，大東支付電子錢包結帳。不同商品的編號與金額如表所示。結帳系統會先讀取電子錢包餘額，再依購買商品編號結帳後(輸入-1表示結帳)，顯示結帳結果。\n• 若電子錢包餘額足夠，請輸出：「結帳成功,餘額剩x元」\n• 若餘額不足，請輸出：「餘額不足,請另外加值y元」\n【商品清單】\n1. 電競滑鼠：3490\n2. 電競鍵盤：7990\n3. 電腦椅：3990\n4. 電腦機殼：2590\n5. 電腦桌：6890\n6. 記憶體 16GB一條：3490\n7. SSD256GB一條：1490",examples:[{input:"10000\n1\n4\n-1",output:"結帳成功,餘額剩3920元",explanation:"電子錢包帳戶中原有10000元，消費3490+2590=6080 結帳成功,餘額剩3920元"},{input:"5000\n3\n5\n-1",output:"餘額不足,請另外加值5880元",explanation:"電子錢包帳戶中原有5000元，消費3990+6890=10880 餘額不足,請另外加值5880元"}],testCases:[{input:"5000 3 5 -1",expectedOutput:"餘額不足,請另外加值5880元",score:10},{input:"10000 1 4 -1",expectedOutput:"結帳成功,餘額剩3920元",score:10},{input:"8000 6 7 3 -1",expectedOutput:"餘額不足,請另外加值970元",score:10},{input:"20000 5 1 6 -1",expectedOutput:"結帳成功,餘額剩6130元",score:10},{input:"10000 1 4 -1",expectedOutput:"結帳成功,餘額剩3920元",score:10},{input:"5000 -1",expectedOutput:"結帳成功,餘額剩5000元",score:10},{input:"10000 2 -1",expectedOutput:"結帳成功,餘額剩2010元",score:10},{input:"1000 7 -1",expectedOutput:"餘額不足,請另外加值490元",score:10},{input:"30000 2 2 2 -1",expectedOutput:"結帳成功,餘額剩6030元",score:10},{input:"0 4 -1",expectedOutput:"餘額不足,請另外加值2590元",score:10}],difficulty:"L2",sb3Path:"m0/114JTaitung/Taitung-J-4.sb3"}]}}}]);